      "against": [
        { "text": "천명의 성상(흡기/호기), 목소리 변화, 삼킴 곤란 등 상기도 단서 미확인", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "야간 증상이 누우면 악화되고 앉으면 호전되는지, 다리 부종·야간뇨·최근 체중 증가가 있는지(심부전 감별에 가장 판별력 큼)"
  ],
  "suggested_tests": [
    { "name": "흉부 X선", "purpose": "심부전(폐울혈)·폐질환 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "폐기능검사(기관지확장제 반응 포함)", "purpose": "가변적 기류 제한 확인", "urgency": "routine", "basis": "guideline" },
